def is_power_of_five(num):
    if num <= 0:
        return False
    if num == 1:
        return True
    while num % 5 == 0:
        num //= 5
    return num == 1

results = {}
for n in range(3, 21):
    value = (2**n) - 3
    is_power = is_power_of_five(value)
    results[n] = (value, is_power)

print("n | 2^n - 3 | Is Power of 5")
print("-" * 40)
for n, (value, is_power) in results.items():
    print(f"{n:2} | {value:7} | {is_power}")

# Collect the successful values of n
successful_n = [n for n, (value, is_power) in results.items() if is_power]
print("\nSuccessful n values:", successful_n)

def is_power_of_five(num):
    if num <= 0:
        return False
    while num > 1:
        if num % 5 != 0:
            return False
        num //= 5
    return True

# Test small cases where n = 4m + 3
N_values = [3, 7, 11, 15, 19, 23]
solutions = []
for n in N_values:
    val = 2**n - 3
    if is_power_of_five(val):
        solutions.append(n)

print(f"Solutions found in tested range: {solutions}")
